class Solution {
    private fun lowerBound(values:LongArray,target:Long):Int{
        var left=0;
        var right=values.size;
        while(left<right){
            val middle=(left+right) ushr 1;
            if(values[middle]<target)left=middle+1 else right=middle
        };
        return left
    }
    fun findMaximumLength(nums:IntArray):Int{
        val n=nums.size;
        val prefix=LongArray(n+1);
        for(i in nums.indices)prefix[i+1]=prefix[i]+nums[i].toLong();
        val dp=IntArray(n+1);
        val bestPrevious=IntArray(n+2);
        for(end in 1..n){
            bestPrevious[end]=maxOf(bestPrevious[end],bestPrevious[end-1]);
            val cut=bestPrevious[end];
            dp[end]=dp[cut]+1;
            val need=2L*prefix[end]-prefix[cut];
            val next=lowerBound(prefix,need);
            if(next<=n)bestPrevious[next]=maxOf(bestPrevious[next],end)
        };
        return dp[n]
    }
}

